  const visited = new Map<string, number>(); // 0=unvisited, 1=visiting, 2=done
  function dfs(node: string): boolean {
    if (visited.get(node) === 1) return true; // Cycle!
    if (visited.get(node) === 2) return false;
    visited.set(node, 1);
    for (const neighbor of graph.get(node) || []) {
      if (dfs(neighbor)) return true;
    }
    visited.set(node, 2);
    return false;
  }
  for (const node of graph.keys()) if (dfs(node)) return true;
  return false;
}

